        (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND deleted = 0) AS totalCount,
        (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1 AND deleted = 0) AS completedCount
      FROM projects p ORDER BY p.id
